using FamilyVeda.Application.Common;
using FamilyVeda.Infrastructure.Records;
using FluentAssertions;
using Microsoft.Extensions.Configuration;

namespace FamilyVeda.UnitTests;

// Stand-in pdfinfo/pdftotext scripts keep these tests independent of poppler being installed.
public sealed class PdfReportLimitTests : IDisposable
{
    private readonly DirectoryInfo _directory = Directory.CreateTempSubdirectory("fv-pdf-limit-");

    [Fact]
    public async Task ExtractText_RejectsPdfLongerThanFourPages_WithoutReadingIt()
    {
        var service = CreateService(pages: 5, layoutText: "Haemoglobin    12.4    g/dL    11.0 - 15.0");

        var act = () => service.ExtractTextAsync(PdfPath(), CancellationToken.None);

        (await act.Should().ThrowAsync<ProcessingException>()).WithMessage("This report has 5 pages. Reports longer than 4 pages cannot be read automatically.*");
    }

    [Fact]
    public async Task ExtractText_ReadsTextLayerDirectly_ForDigitalPdfWithinLimit()
    {
        const string layout = "FULL BLOOD COUNT\nTest              Result    Units     Reference Range\nHaemoglobin       12.4      g/dL      11.0 - 15.0\n";
        var service = CreateService(pages: 4, layoutText: layout);

        var text = await service.ExtractTextAsync(PdfPath(), CancellationToken.None);

        LabExtractionService.ParseValues(text).Should().ContainSingle().Which.Should().Be(
            new LabExtractionService.ParsedLabValue("Haemoglobin", 12.4m, "g/dL", 11.0m, 15.0m));
    }

    [Fact]
    public async Task ExtractText_RejectsTextBeyondCharacterLimit()
    {
        var service = CreateService(pages: 1, layoutText: new string('x', 1_500), maxCharacters: 1_000);

        var act = () => service.ExtractTextAsync(PdfPath(), CancellationToken.None);

        await act.Should().ThrowAsync<ProcessingException>().WithMessage("This report contains too much text*");
    }

    private TesseractOcrService CreateService(int pages, string layoutText, int maxCharacters = 60_000)
    {
        var layoutFile = Path.Combine(_directory.FullName, "layout.txt");
        File.WriteAllText(layoutFile, layoutText);
        var configuration = new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string, string?>
        {
            ["Ocr:PdfInfoCommand"] = Script("pdfinfo", $"echo 'Title: synthetic'\necho 'Pages:          {pages}'"),
            ["Ocr:PdfTextCommand"] = Script("pdftotext", $"cat '{layoutFile}'"),
            ["Ocr:PdfRenderCommand"] = Script("pdftoppm", "exit 1"),
            ["Ocr:MaxPages"] = "4",
            ["Ocr:MaxOutputCharacters"] = maxCharacters.ToString(System.Globalization.CultureInfo.InvariantCulture)
        }).Build();
        return new TesseractOcrService(configuration);
    }

    private string Script(string name, string body)
    {
        var path = Path.Combine(_directory.FullName, name);
        File.WriteAllText(path, $"#!/bin/sh\n{body}\n");
        File.SetUnixFileMode(path, UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute);
        return path;
    }

    private string PdfPath()
    {
        var path = Path.Combine(_directory.FullName, "synthetic-report.pdf");
        File.WriteAllText(path, "%PDF-1.4 synthetic");
        return path;
    }

    public void Dispose() => _directory.Delete(recursive: true);
}
